import{_ as t,o as l,c as r,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Testing Weekly 2018-11-28","description":"","frontmatter":{"title":"Ceph Testing Weekly 2018-11-28","date":"2018-11-28T00:00:00.000Z","updated":"2018-11-29T00:00:00.000Z","tags":["Ceph","Python 3","OpenSUSE","Installer Interface","Orchestrator Module"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Testing_Weekly_2018-11-28.md","filePath":"posts/2018/Ceph_Testing_Weekly_2018-11-28.md","lastUpdated":1780460162000}'),o={name:"posts/2018/Ceph_Testing_Weekly_2018-11-28.md"};function a(s,e,i,p,h,S){return l(),r("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 多位Ceph研发人员（包括但不限于Nathan, David Galloway, Alfredo, Sebastian等）</p><p><strong>会议主题</strong>： 讨论Ceph项目中Python 3的支持、安装器接口、Orchestrator模块以及OpenSUSE测试等议题。</p><p><strong>会议内容</strong>：</p><p><strong>1. Python 3支持</strong></p><ul><li>讨论了在Ceph项目中引入Python 3的必要性，以及如何在openSUSE上实现Python 3环境。</li><li>提到了使用Mach工具进行OpenSUSE构建的可行性，并讨论了如何解决Shaman构建工具的限制。</li><li>认为需要投入资源来支持OpenSUSE的构建，并考虑使用OBS或mock工具。</li></ul><p><strong>2. 安装器接口</strong></p><ul><li>讨论了Ceph安装器接口的改进，包括Ansible和Sensu等工具的使用。</li><li>讨论了安装器接口的抽象化，以及如何支持不同类型的安装器。</li><li>认为需要创建一个产品跟踪器（tracker），以便跟踪相关需求和问题。</li></ul><p><strong>3. Orchestrator模块</strong></p><ul><li>讨论了Orchestrator模块的设计和实现，以及其与Ceph Manager的集成。</li><li>认为Orchestrator模块可以提供统一的命令接口，支持不同类型的Orchestrator，例如Ansible、DeepSea和Rook等。</li><li>认为Orchestrator模块的开发需要与安装器接口的改进同步进行。</li></ul><p><strong>4. OpenSUSE测试</strong></p><ul><li>讨论了在OpenSUSE上测试Ceph项目的可行性，以及如何解决Shaman构建工具的限制。</li><li>认为需要投入资源来支持OpenSUSE的构建，并考虑使用OBS或mock工具。</li></ul><p><strong>行动计划</strong>：</p><ul><li>Nathan将继续开发Orchestrator模块，并与安装器接口的改进同步进行。</li><li>David Galloway将创建一个产品跟踪器，以便跟踪相关需求和问题。</li><li>讨论如何支持OpenSUSE的构建，并考虑使用OBS或mock工具。</li></ul><p><strong>关键信息</strong>：</p><ul><li>Ceph项目正在积极推动Python 3的支持。</li><li>Ceph项目正在改进安装器接口，并引入Orchestrator模块。</li><li>OpenSUSE测试是Ceph项目的一个重要目标。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些技术细节，例如Mach、mock、OBS、Shaman等，这些内容对于理解会议内容可能有所帮助。</li><li>会议中提到了一些资源问题，例如构建资源、测试环境等，这些内容对于后续工作可能有所帮助。</li></ul>',19)])])}const g=t(o,[["render",a]]);export{_ as __pageData,g as default};
